def write(doc, add_heading_1, add_heading_2, add_heading_3, add_p, add_bullet, add_code, style_table):
    add_heading_1("CHƯƠNG 1. GIỚI THIỆU ĐỀ TÀI")

    add_heading_2("1.1. Đặt vấn đề và Lý do chọn đề tài")
    add_p("Trong kỷ nguyên công nghệ số và sự bùng nổ của mạng lưới Internet toàn cầu, khối lượng thông tin và dữ liệu văn bản được tạo ra mỗi giây đang gia tăng với một tốc độ hàm số mũ. Hiện tượng này thường được giới khoa học gọi là \"Bùng nổ Thông tin\" (Information Explosion) hoặc \"Quá tải Thông tin\" (Information Overload). Sự dư thừa thông tin mang lại cho con người nguồn tri thức vô tận nhưng đồng thời cũng tạo ra rào cản to lớn trong việc tiếp thu, chọn lọc và xử lý nội dung. Hàng ngày, một người dùng bình thường hoặc các chuyên gia phân tích dữ liệu phải tiếp xúc với hàng ngàn bài báo tin tức, tài liệu nghiên cứu học thuật, báo cáo tài chính và vô vàn các văn bản điện tử khác. Khả năng đọc hiểu của con người là có giới hạn, do đó, việc phải đọc toàn bộ nội dung của những văn bản dài hàng ngàn từ để tìm kiếm các ý chính đã trở thành một công việc mất rất nhiều thời gian và công sức, giảm hiệu suất lao động nghiêm trọng.")
    add_p("Chính vì lý do này, Tóm tắt văn bản tự động (Automatic Text Summarization - ATS) đã trở thành một trong những lĩnh vực nghiên cứu trọng điểm, đầy thách thức và vô cùng cấp thiết trong chuyên ngành Xử lý Ngôn ngữ Tự nhiên (Natural Language Processing - NLP) và Trí tuệ Nhân tạo (Artificial Intelligence - AI). Mục tiêu tối thượng của Tóm tắt văn bản tự động là sử dụng các thuật toán học máy, học sâu để mô phỏng khả năng đọc hiểu của con người, qua đó rút gọn một bài văn bản dài thành một văn bản ngắn gọn, cô đọng hơn rất nhiều nhưng vẫn phải đảm bảo tính nguyên vẹn của thông tin cốt lõi, không làm sai lệch ý nghĩa và ngữ cảnh gốc của bài viết.")
    add_p("Tuy nhiên, bất chấp những tiến bộ vượt bậc của Trí tuệ Nhân tạo trong những năm gần đây, bài toán Tóm tắt văn bản trích xuất (Extractive Summarization) vẫn đang đối mặt với hàng loạt rào cản kỹ thuật khắt khe, đòi hỏi sự nghiên cứu chuyên sâu để vượt qua:")
    add_bullet("Hạn chế của mô hình đơn giản (Heuristic Models): Các mô hình thủ công dựa trên kinh nghiệm như thuật toán Lead-3 (chỉ lấy đúng 3 câu đầu tiên của bài báo) mắc phải hiện tượng Lead Bias rất nặng [7], [13]. Thuật toán này bỏ qua hoàn toàn nội dung thân bài và kết luận, dẫn đến điểm đa dạng thông tin (Diversity Score) gần như bằng 0. Mặc dù nó hoạt động tương đối tốt trên báo chí phương Tây, nhưng lại thất bại thảm hại khi áp dụng vào các văn bản có cấu trúc phức tạp hơn.", "Thứ nhất, ")
    add_bullet("Hạn chế của mô hình dựa trên bề mặt từ vựng (Lexical Matching): Các thuật toán phân tích đồ thị kinh điển như TextRank (PageRank applied to text) [6] hay TF-IDF chỉ đánh giá độ quan trọng của câu thông qua sự trùng lặp từ vựng bề mặt (Surface Lexical Overlap). Chúng hoàn toàn bất lực và mù lòa trước các hiện tượng từ đồng nghĩa (Synonyms), đa nghĩa (Polysemy), hoặc khi tác giả sử dụng các lối diễn đạt uyển chuyển, bóng bẩy (Paraphrasing) mà không lặp lại từ khóa cũ.", "Thứ hai, ")
    add_bullet("Sự thiếu hụt dữ liệu và rào cản của Ngôn ngữ Tiếng Việt (Vietnamese NLP Bottlenecks): Đối với các ngôn ngữ ít tài nguyên như Tiếng Việt, các mô hình học sâu chưa qua tinh chỉnh (Zero-shot Pretrained SBERT) thường biểu diễn vector câu một cách phân tán ngẫu nhiên. Tiếng Việt là ngôn ngữ đơn lập (isolating language), nơi các từ ghép được tạo thành từ nhiều âm tiết rời rạc nhưng lại mang một ý nghĩa hợp nhất. Sự kém sắc nét của không gian vector (Vector Space Dullness) khiến các thuật toán phân cụm toán học đằng sau chọn nhầm các câu phụ, hoặc các câu chứa nhiều từ chức năng (Stopwords) thay vì các câu mang thông tin lõi.", "Thứ ba, ")
    add_p("Để giải quyết bài toán này một cách triệt để, nhóm nghiên cứu quyết định lựa chọn 2 tập dữ liệu chuẩn mực nhất thế giới hiện nay để làm nền tảng đánh giá và huấn luyện:")
    add_bullet("Tập dữ liệu CNN/DailyMail (Tiếng Anh): Đây là bộ dữ liệu chuẩn mực (Gold Standard Benchmark) hàng đầu thế giới, được sử dụng trong hơn 90% các bài báo khoa học đỉnh cao công bố tại ACL, EMNLP, NeurIPS về bài toán tóm tắt văn bản [7]. Sử dụng bộ dữ liệu này không chỉ giúp kiểm chứng năng lực của mô hình một cách khách quan mà còn đảm bảo phương pháp luận và quy trình đánh giá của Đồ án tuân thủ chặt chẽ các tiêu chuẩn khắt khe trong môi trường nghiên cứu học thuật quốc tế.", "")
    add_bullet("Tập dữ liệu VietNews / VNDS (Tiếng Việt) [18]: Với mục tiêu giải quyết bài toán địa phương và đánh giá năng lực của các mô hình Xử lý ngôn ngữ tự nhiên Tiếng Việt (Vietnamese Bi-Encoder), chúng tôi sử dụng tập dữ liệu tin tức báo chí trong nước thu thập từ VnExpress, Tuổi Trẻ, Dân Trí. Điều này giúp đánh giá khả năng hiểu ngữ cảnh của kiến trúc Transformer sâu trên một môi trường phức tạp, sau khi văn bản đã được chuẩn hóa bởi các công cụ tiền xử lý tách từ ghép tiêu chuẩn, qua đó chứng minh khả năng áp dụng thương mại hóa vào thị trường truyền thông Việt Nam.", "")
    add_p("Từ những tiền đề và thách thức đã phân tích sâu sắc ở trên, nhóm nghiên cứu đã lựa chọn đề tài \"Hệ thống Tóm tắt Văn bản Trích xuất Song ngữ dựa trên Quy trình 2 Giai đoạn: SBERT Fine-Tuned, K-Means Selection và Post-Filtering\" làm định hướng cho Đồ án. Đây không chỉ là một công trình mang tính nghiên cứu học thuật thuần túy, mà còn là một sản phẩm phần mềm mang tính ứng dụng thực tiễn cao, giải quyết trực tiếp bài toán \"Quá tải thông tin\" trong kỷ nguyên số.")

    add_heading_2("1.2. Mục tiêu nghiên cứu")
    add_p("Mục tiêu của đề tài không chỉ dừng lại ở việc áp dụng một mô hình có sẵn, mà là nghiên cứu bản chất toán học, tinh chỉnh chuyên sâu, và xây dựng một quy trình hoàn chỉnh từ thu thập dữ liệu, huấn luyện, đến triển khai sản phẩm phần mềm. Cụ thể, các mục tiêu trọng tâm bao gồm:")
    add_bullet("Nghiên cứu nền tảng Lý thuyết chuyên sâu: Tìm hiểu cặn kẽ bản chất của bài toán Tóm tắt văn bản trích xuất (Extractive Summarization). Đi sâu phân tích kiến trúc mạng SBERT (Bi-Encoder), sự khác biệt giữa BERT và Sentence-BERT, nguyên lý hoạt động của thuật toán K-Means Clustering trong không gian High-dimensional, và sự cần thiết của Bộ chỉ số đánh giá kép (Dual-Evaluation Framework) bao gồm cả chỉ số Ngoại tại và Nội tại.")
    add_bullet("Tối ưu hóa và Huấn luyện Học có giám sát (Supervised Fine-Tuning): Thực hiện quá trình Fine-Tune mô hình SBERT bằng việc sử dụng hàm mất mát tinh vi CosineSimilarityLoss. Mô hình được huấn luyện trên tập dữ liệu cặp câu Oracle lý tưởng, được trích xuất bằng thuật toán ROUGE-1 Oracle Matching tự động từ bộ dữ liệu chuẩn, nhằm thay đổi hình học không gian vector câu (Vector Space Geometry), ép các câu mang ý chính hội tụ và đẩy các câu rác ra xa.")
    add_bullet("Nghiên cứu và Phát triển Thuật toán Lựa chọn Thích ứng (Adaptive Selection): Đề xuất và chứng minh tính hiệu quả của Thuật toán Dynamic Adaptive K. Thay vì ép buộc mô hình trích xuất số lượng câu cố định, thuật toán tính toán động số câu cần nén dựa trên tỷ lệ toán học hàm K = round(N * alpha * scale) kết hợp với luật suy giảm vị trí (Position-aware Scaling), đảm bảo giữ được sự tự nhiên của bản tóm tắt.")
    add_bullet("Thương mại hóa và Đóng gói Sản phẩm Phần mềm (Software Engineering): Chuyển hóa các thành quả nghiên cứu học thuật thành một ứng dụng Web App Full-Stack hoàn thiện. Xây dựng backend bằng FastAPI REST API với kỹ thuật quản lý bộ nhớ Singleton Pattern, thiết kế frontend bằng React Vite kết hợp TailwindCSS mang lại trải nghiệm tương tác trực quan (Interactive Highlighting), và cuối cùng là đóng gói toàn bộ hệ thống bằng Docker Compose để triển khai (Deploy) dễ dàng lên các hệ thống máy chủ VPS đám mây.")

    add_heading_2("1.3. Phạm vi nghiên cứu")
    add_p("Để đảm bảo tính khả thi, độ tin cậy của dữ liệu và tập trung tối đa vào độ sâu của nghiên cứu, đề tài được giới hạn trong các phạm vi cụ thể như sau:")
    add_bullet("Phạm vi Dữ liệu Tiếng Việt: Sử dụng tập dữ liệu báo chí chuẩn mực VietNews (hay còn gọi là VNDS - Vietnamese News Dataset) [18]. Tập thử nghiệm (Test Set) được trích xuất độc lập hoàn toàn với N=200 bài báo ngẫu nhiên, không xuất hiện trong tập huấn luyện (No Data Leakage). Dữ liệu bao phủ nhiều lĩnh vực như Chính trị, Xã hội, Thể thao, Công nghệ, và Kinh tế.")
    add_bullet("Phạm vi Dữ liệu Tiếng Anh: Sử dụng tập dữ liệu báo chí quốc tế CNN/DailyMail (phiên bản non-anonymized 3.0.0 trên Hugging Face). Quá trình thực nghiệm cũng thực hiện trên N=200 bài báo thử nghiệm độc lập thuộc tập Test. Đây là các bài báo có độ dài lớn, cấu trúc tin tức phương Tây đặc thù (Inverted Pyramid).")
    add_bullet("Phạm vi Kiến trúc AI Core: Nghiên cứu tập trung hoàn toàn vào Kiến trúc SBERT Bi-Encoder (Vietnamese Bi-Encoder / PhoBERT cho Tiếng Việt và all-mpnet-base-v2 cho Tiếng Anh). Đề tài không đi sâu vào các cấu trúc sinh ngôn ngữ tự hồi quy (Autoregressive LLMs như GPT-3, GPT-4, LLaMA) hay cấu trúc Sequence-to-Sequence (BART, T5) do giới hạn về phần cứng huấn luyện và mục tiêu bám sát phương pháp trích xuất (Extractive).")
    add_bullet("Phạm vi Ứng dụng: Xây dựng nền tảng Web có khả năng Tóm tắt văn bản thô (Raw Text), Tóm tắt trực tiếp qua đường link URL của bài báo (sử dụng thư viện bóc tách newspaper3k), và Tổng hợp tin tức nóng 24h từ các bộ máy tìm kiếm (DuckDuckGo News Engine).")

    add_heading_2("1.4. Phương pháp nghiên cứu")
    add_p("Để đạt được các mục tiêu đã đề ra và chứng minh tính đúng đắn của phương pháp một cách thuyết phục nhất, đồ án áp dụng kết hợp ba phương pháp luận nghiên cứu chính:")
    add_bullet("Phương pháp Nghiên cứu Lý thuyết Cơ bản (Theoretical Research): Khảo sát, phân tích, tổng hợp các bài báo khoa học đỉnh cao quốc tế (từ các hội nghị ACL, EMNLP, ICLR) để xây dựng hệ thống cơ sở lý thuyết vững chắc về Word/Sentence Embedding, kiến trúc Transformer, hiện tượng Anisotropy, toán học về thuật toán phân cụm, và bản chất của các độ đo hiệu năng.")
    add_bullet("Phương pháp Thực nghiệm Đối chứng và Phân tích Định lượng (Empirical Benchmark & Quantitative Analysis): Thực hiện phương pháp đào tạo mô hình bằng học máy có giám sát (Supervised Learning). Sau đó, tiến hành kiểm thử và so sánh hiệu năng (Benchmarking) của phương pháp đề xuất với các phương pháp Baseline truyền thống (Lead-3, TextRank, Pretrained SBERT). Sử dụng Khung đánh giá kép (Dual-Evaluation Framework) bao gồm hệ thống các công thức ROUGE-1, ROUGE-2, ROUGE-L [9], BERTScore F1 [10] (Chỉ số Ngoại tại) và Silhouette Score [19], Diversity Score [11], Compression Ratio [16], [17] (Chỉ số Nội tại). Phân tích chi tiết các con số toán học để rút ra kết luận.")
    add_bullet("Phương pháp Nghiên cứu Kỹ thuật Phần mềm (Software Engineering & Development): Vận dụng các quy trình phát triển phần mềm Agile, thiết kế kiến trúc hệ thống 3 Tầng (Three-Tier Architecture), phân tích thiết kế API RESTful, và áp dụng triệt để các kỹ thuật tối ưu hóa tài nguyên (Memory Optimization) để chuyển hóa một mô hình AI nghiên cứu thành một sản phẩm có tính ứng dụng thực tiễn cao.")

    add_heading_2("1.5. Ý nghĩa của đề tài")
    add_p("Đề tài mang lại những ý nghĩa thiết thực và những đóng góp mới mẻ, phân chia rõ rệt thành hai khía cạnh: Học thuật và Thực tiễn.")
    add_p("Về mặt Học thuật (Academic Contributions):", bold_prefix="1. ")
    add_bullet("Nghiên cứu đã cung cấp những bằng chứng thực nghiệm rõ ràng, mang tính định lượng cao, chứng minh rằng sự cần thiết của việc Supervised Fine-Tuning đối với các mô hình Tiếng Việt là hoàn toàn sống còn. Việc này giúp cải thiện hiệu năng nén văn bản lên mức tối đa (ROUGE-1 tăng vọt +8.18%, độ sắc nét cụm Silhouette tăng +43.6% so với Pretrained gốc).")
    add_bullet("Đóng góp trực tiếp cho cộng đồng nguồn mở NLP Việt Nam bằng việc công bố và xuất bản công khai trọng số mô hình đã được tinh chỉnh lên nền tảng Hugging Face Model Hub tại địa chỉ: kttt294/vietnamese-sbert-finetuned. Bất kỳ nhà nghiên cứu hay sinh viên nào cũng có thể kế thừa và tái sử dụng mô hình này một cách dễ dàng chỉ bằng một dòng code API.")
    add_bullet("Làm sáng tỏ và có những phân tích chuyên sâu giải mã hiện tượng 'Semantic Density Compression', mâu thuẫn đánh đổi giữa Diversity Score [11] và ROUGE-1 [9], cũng như hiện tượng 'Lead Bias' [7], [13] mang đặc thù văn hóa báo chí giữa Anh và Việt Nam.")
    add_p("Về mặt Thực tiễn (Practical Contributions):", bold_prefix="2. ")
    add_bullet("Phát triển thành công một giải pháp phần mềm toàn diện, đóng gói sẵn sàng dưới dạng Docker Compose, có thể triển khai lên bất kỳ máy chủ Linux, Windows hoặc Cloud Server nào trong vòng chưa tới 5 phút.")
    add_bullet("Cung cấp một công cụ mạnh mẽ, giao diện thân thiện cho người dùng cuối (Nhà báo, Sinh viên, Nhà phân tích dữ liệu) giúp họ tiết kiệm đến 80% thời gian đọc hiểu tin tức mỗi ngày. Ứng dụng tích hợp các tính năng tiên tiến như cào tin thời sự 24h, tự động làm sáng (Highlight) các câu trọng điểm trong bài báo, mang lại trải nghiệm người dùng hiện đại và cao cấp.")
    
    add_p("Như vậy, thông qua Chương 1, nhóm nghiên cứu đã phác họa bức tranh toàn cảnh về lý do ra đời của hệ thống, xác định rõ ràng mục tiêu, giới hạn phạm vi nghiên cứu, và khẳng định tầm quan trọng của việc giải quyết bài toán tóm tắt văn bản trích xuất trên nền tảng Trí tuệ Nhân tạo hiện đại.")
